text:
{
  "analysis": {
    "statement": "Cho tam giác $ABC$ vuông tại $A$, đường cao $AH$. Gọi $D$, $E$ lần lượt là hình chiếu của $H$ trên $AB$ và $AC$. Chứng minh $AD \\cdot AB = AE \\cdot AC$.",
    "language": "vi",
    "topic": "geometry",
    "subtopic": "similar triangles and relations in a right triangle",
    "gradeLevel": 9,
    "withinCurriculum": true,
    "concepts": ["tam giác vuông", "đường cao", "tam giác đồng dạng", "tính chất hình chiếu"],
    "givens": ["Tam giác $ABC$ vuông tại $A$ ($\\angle A = 90^\\circ$)", "$AH \\perp BC$ ($\\angle AHB = \\angle AHC = 90^\\circ$)", "$HD \\perp AB$ ($\\angle HDA = 90^\\circ$)", "$HE \\perp AC$ ($\\angle HEA = 90^\\circ$)"],
    "unknowns": ["Chứng minh đẳng thức $AD \\cdot AB = AE \\cdot AC$"],
    "constraints": ["Các điểm $D, E$ nằm trên các cạnh $AB, AC$"],
    "status": "solvable",
    "statusReason": null,
    "interpretationNotes": []
  },
  "strategy": "Ta sẽ chứng minh đẳng thức bằng cách sử dụng tính chất hình chiếu trong tam giác vuông. Đầu tiên, ta chứng minh $\\triangle AHD \\sim \\triangle ABH$ để suy ra $AD \\cdot AB = AH^2$. Tiếp theo, ta chứng minh $\\triangle AHE \\sim \\triangle ACH$ để suy ra $AE \\cdot AC = AH^2$. Cuối cùng, bằng cách so sánh hai kết quả này, ta sẽ chứng minh được điều cần chứng minh.",
  "hints": [
    {
      "id": "h1",
      "level": 1,
      "question": "Hãy quan sát tam giác $AHD$ và tam giác $ABH$. Chúng có góc nào bằng nhau ngoài góc vuông?",
      "cue": "góc chung",
      "explanation": "Hai tam giác này đều có một góc vuông ($\\angle ADH$ và $\\angle AHB$). Bạn thử tìm xem góc nào là góc chung của hai tam giác này nhé.",
      "math": null,
      "stepId": "3",
      "focus": ["ang_HDA", "ang_AHB", "ang_DAH", "ang_BAH"]
    },
    {
      "id": "h2",
      "level": 2,
      "question": "Khi đã chứng minh được hai tam giác đồng dạng, ta sẽ có hệ thức tỉ số giữa các cạnh tương ứng như thế nào?",
      "cue": "tỷ số cạnh tương ứng",
      "explanation": "Nếu $\\triangle AHD \\sim \\triangle ABH$ thì tỉ số giữa cạnh huyền và cạnh góc vuông kề với góc chung sẽ bằng nhau. Hãy viết ra hệ thức liên hệ $AD, AH, AB$.",
      "math": "\\frac{AD}{AH} = \\frac{AH}{AB}",
      "stepId": "4",
      "focus": ["seg_AD", "seg_AH", "seg_AB"]
    },
    {
      "id": "h3",
      "level": 1,
      "question": "Bây giờ hãy làm tương tự với tam giác $AHE$ và tam giác $ACH$. Bạn có thể chứng minh chúng đồng dạng theo cách tương tự không?",
      "cue": "góc vuông và góc chung",
      "explanation": "Tam giác $AHE$ cũng có góc vuông tại $E$ và góc $A$ chung với tam giác $ACH$. Hãy lập hệ thức tương tự cho $AE, AH, AC$.",
      "math": "\\frac{AE}{AH} = \\frac{AH}{AC}",
      "stepId": "7",
      "focus": ["seg_AE", "seg_AH", "seg_AC"]
    },
    {
      "id": "h4",
      "level": 3,
      "question": "Từ hai hệ thức $AD \\cdot AB = AH^2$ và $AE \\cdot AC = AH^2$ vừa tìm được, bạn có thể kết luận gì?",
      "cue": "suy luận bằng bắc cầu",
      "explanation": "Vì cả hai tích đều bằng $AH^2$ nên chúng bằng nhau. Hãy viết lại kết quả cuối cùng.",
      "math": "AD \\cdot AB = AH^2 = AE \\cdot AC",
      "stepId": "9",
      "focus": ["seg_AD", "seg_AB", "seg_AE", "seg_AC"]
    }
  ],
  "steps": [
    {
      "id": "1",
      "title": "Xét tam giác $AHD$ và $ABH$",
      "explanation": "Ta xét hai tam giác $AHD$ và $ABH$. Vì $HD \\perp AB$ nên $\\angle ADH = 90^\\circ$. Vì $AH \\perp BC$ nên $\\angle AHB = 90^\\circ$.",
      "math": "\\angle ADH = \\angle AHB = 90^\\circ",
      "reason": "Định nghĩa đường cao và hình chiếu",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_HDA", "ang_AHB"]}
      ]
    },
    {
      "id": "2",
      "title": "Tìm góc chung",
      "explanation": "Hai tam giác này còn có một góc chung là $\\angle DAH$ (cùng là $\\angle BAH$).",
      "math": "\\angle DAH = \\angle BAH",
      "reason": "Góc chung",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_DAH", "ang_BAH"]}
      ]
    },
    {
      "id": "3",
      "title": "Chứng minh $\\triangle AHD \\sim \\triangle ABH$",
      "explanation": "Hai tam giác có hai cặp góc tương ứng bằng nhau ($\\angle ADH = \\angle AHB$ và $\\angle DAH = \\angle BAH$), nên chúng đồng dạng.",
      "math": "\\triangle AHD \\sim \\triangle ABH (g.g)",
      "reason": "Định lý đồng dạng tam giác (g.g)",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_HDA", "ang_AHB", "ang_DAH", "ang_BAH"]}
      ]
    },
    {
      "id": "4",
      "title": "Lập hệ thức từ đồng dạng",
      "explanation": "Từ hai tam giác đồng dạng, ta có tỉ số giữa cạnh huyền và cạnh góc vuông kề với góc chung bằng nhau.",
      "math": "\\frac{AD}{AH} = \\frac{AH}{AB}",
      "reason": "Tỉ số cạnh tương ứng của tam giác đồng dạng",
      "geometryActions": [
        {"action": "highlight", "targets": ["seg_AD", "seg_AH", "seg_AB"]}
      ]
    },
    {
      "id": "5",
      "title": "Suy ra $AD \\cdot AB = AH^2$",
      "explanation": "Từ tỉ số $\\frac{AD}{AH} = \\frac{AH}{AB}$, ta nhân chéo hai vế để có hệ thức tích. Đây là tính chất hình chiếu của cạnh huyền lên đường cao.",
      "math": "AD \\cdot AB = AH^2",
      "reason": "Nhân chéo",
      "geometryActions": []
    },
    {
      "id": "6",
      "title": "Xét tam giác $AHE$ và $ACH$",
      "explanation": "Tương tự, ta xét hai tam giác $AHE$ và $ACH$. Vì $HE \\perp AC$ nên $\\angle HEA = 90^\\circ$. Vì $AH \\perp BC$ nên $\\angle AHC = 90^\\circ$.",
      "math": "\\angle HEA = \\angle AHC = 90^\\circ",
      "reason": "Định nghĩa đường cao và hình chiếu",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_HEA", "ang_AHC"]}
      ]
    },
    {
      "id": "7",
      "title": "Tìm góc chung",
      "explanation": "Hai tam giác này có một góc chung là $\\angle HAE$ (cùng là $\\angle HAC$).",
      "math": "\\angle HAE = \\angle HAC",
      "reason": "Góc chung",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_HAE", "ang_HAC"]}
      ]
    },
    {
      "id": "8",
      "title": "Chứng minh $\\triangle AHE \\sim \\triangle ACH$",
      "explanation": "Hai tam giác có hai cặp góc tương ứng bằng nhau ($\\angle HEA = \\angle AHC$ và $\\angle HAE = \\angle HAC$), nên chúng đồng dạng.",
      "math": "\\triangle AHE \\sim \\triangle ACH (g.g)",
      "reason": "Định lý đồng dạng tam giác (g.g)",
      "geometryActions": [
        {"action": "highlight", "targets": ["ang_HEA", "ang_AHC", "ang_HAE", "ang_HAC"]}
      ]
    },
    {
      "id": "9",
      "title": "Lập hệ thức từ đồng dạng",
      "explanation": "Từ hai tam giác đồng dạng, ta có tỉ số giữa cạnh huyền và cạnh góc vuông kề với góc chung bằng nhau.",
      "math": "\\frac{AE}{AH} = \\frac{AH}{AC}",
      "reason": "Tỉ số cạnh tương ứng của tam giác đồng dạng",
      "geometryActions": [
        {"action": "highlight", "targets": ["seg_AE", "seg_AH", "seg_AC"]}
      ]
    },
    {
      "id": "10",
      "title": "Suy ra $AE \\cdot AC = AH^2$",
      "explanation": "Từ tỉ số $\\frac{AE}{AH} = \\frac{AH}{AC}$, ta nhân chéo hai vế để có hệ thức tích.",
      "math": "AE \\cdot AC = AH^2",
      "reason": "Nhân chéo",
      "geometryActions": []
    },
    {
      "id": "11",
      "title": "Kết luận",
      "explanation": "Ta vừa chứng minh được $AD \\cdot AB = AH^2$ và $AE \\cdot AC = AH^2$. Vậy hai tích này bằng nhau.",
      "math": "AD \\cdot AB = AH^2 = AE \\cdot AC \\Rightarrow AD \\cdot AB = AE \\cdot AC",
      "reason": "Suy luận logic",
      "geometryActions": []
    }
  ],
  "finalAnswer": {
    "text": "Đẳng thức $AD \\cdot AB = AE \\cdot AC$ đã được chứng minh.",
    "math": null
  },
